    const now = Date.now();
    if (p.ts < now - RETENTION_MS || p.ts > now + 5 * 60 * 1000) return false;
    const arr = this.pos[animalId] || (this.pos[animalId] = []);
    if (arr.length && arr[arr.length - 1].ts === p.ts) return false;
    if (arr.some((x) => x.ts === p.ts)) return false;
    arr.push(p);
    if (arr.length > 1 && arr[arr.length - 2].ts > p.ts) arr.sort((a, b) => a.ts - b.ts);
    if (arr.length > MAX_PER_ANIMAL) arr.splice(0, arr.length - MAX_PER_ANIMAL);
